  var lbl = /^[A-Za-z][A-Za-z0-9_-]{0,15}[:=\s]\s*(\S.*)$/.exec(s);
  if(lbl && (depth||0) < 2 && alreadyMasked(lbl[1], (depth||0) + 1)) return true;
