var FILLER = /^(?:your|our|the|this|that|here|goes|value|key|keys|token|secret|password|pass|pwd|api|apikey|changeme|change|replace|insert|example|sample|placeholder|dummy|fake|todo|fixme|xxx|yyy|zzz|none|null|empty|redacted|removed|masked|hidden)$/;

